<?php require 'includes/functions.php';require_login();$pdo=db();$action=$_POST['action']??$_GET['action']??'';$id=(int)($_POST['id']??$_GET['id']??0);if($action==='update'&&$id){$qty=max(1,(int)$_POST['qty']);$size=$_SESSION['cart'][$id]['size']??'';$s=$pdo->prepare('SELECT stock_quantity FROM product_sizes WHERE product_id=? AND size=?');$s->execute([$id,$size]);$_SESSION['cart'][$id]['qty']=min($qty,(int)$s->fetchColumn());flash('success','Cart updated.');go('cart.php');}if($action==='remove'&&$id){unset($_SESSION['cart'][$id]);flash('success','Item removed from cart.');go('cart.php');}if($action==='coupon'){$code=strtoupper(trim($_POST['code']??''));$q=$pdo->prepare("SELECT * FROM coupons WHERE code=? AND status='active' AND expiry_date>=CURDATE() AND used_count<usage_limit");$q->execute([$code]);$c=$q->fetch();if(!$c)flash('danger','Invalid Coupon Code or coupon has expired.');elseif(cart_totals()['subtotal']<$c['minimum_order'])flash('danger','Minimum order amount not reached for this coupon.');else{$_SESSION['coupon']=$c;flash('success','Coupon Applied Successfully');}go('cart.php');}if($action==='clear_coupon'){unset($_SESSION['coupon']);go('cart.php');}$items=cart_items();$totals=cart_totals();$pageTitle='My Cart';require 'includes/header.php';require 'includes/navbar.php'; ?>
<main class="container my-5"><h1 class="section-title">My cart</h1><?php if(!$items): ?><div class="alert alert-secondary">Your cart is empty. <a href="<?=base('products.php')?>">Shop oversized T-shirts</a>.</div><?php else: ?><div class="row g-4"><div class="col-lg-8"><div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Product</th><th>Size</th><th>Price</th><th>Qty</th><th>Subtotal</th><th></th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><img src="<?=base(e($i['image']))?>" width="55" height="55" class="me-2"><a class="text-dark" href="<?=base('product-details.php?id='.$i['id'])?>"><?=e($i['name'])?></a></td><td><?=e($i['size'])?></td><td><?=money($i['unit_price'])?></td><td><form method="post" class="d-flex"><input type="hidden" name="action" value="update"><input type="hidden" name="id" value="<?=$i['id']?>"><input type="number" class="form-control form-control-sm" style="width:65px" name="qty" min="1" max="<?=$i['stock_quantity']?>" value="<?=$i['qty']?>"><button class="btn btn-sm btn-outline-dark">↻</button></form></td><td><?=money($i['unit_price']*$i['qty'])?></td><td><a class="btn btn-sm btn-outline-danger" href="<?=base('cart.php?action=remove&id='.$i['id'])?>">×</a></td></tr><?php endforeach ?></tbody></table></div></div></div><div class="col-lg-4"><div class="card card-body"><h4>Order summary</h4><form method="post" class="input-group mb-3"><input type="hidden" name="action" value="coupon"><input class="form-control" name="code" placeholder="Coupon code"><button class="btn btn-outline-dark">Apply</button></form><?php if(!empty($_SESSION['coupon'])): ?><small class="text-success mb-2"><?=e($_SESSION['coupon']['code'])?> applied · <a href="<?=base('cart.php?action=clear_coupon')?>">Remove</a></small><?php endif ?><div class="d-flex justify-content-between"><span>Subtotal</span><span><?=money($totals['subtotal'])?></span></div><div class="d-flex justify-content-between"><span>Coupon discount</span><span>-<?=money($totals['couponDiscount'])?></span></div><div class="d-flex justify-content-between"><span>Tax (5%)</span><span><?=money($totals['tax'])?></span></div><div class="d-flex justify-content-between"><span>Delivery</span><span><?=money($totals['delivery'])?></span></div><hr><div class="d-flex justify-content-between fw-bold fs-5"><span>Total</span><span><?=money($totals['grand'])?></span></div><a class="btn btn-dark w-100 mt-3" href="<?=base('checkout.php')?>">Secure checkout</a></div></div></div><?php endif ?></main><?php require 'includes/footer.php'; ?>
